const response = $input.all()[0].json;
const scanResult = response.content[0].text;
const today = new Date().toISOString().split('T')[0];

// Telegram message
const telegramMsg = `🔍 *Tech Scan ${today}*\n\n${scanResult}\n\n_Auto-generated every 3 days_`;

// Obsidian note
const obsidianNote = `# Tech Scan ${today}\n\n${scanResult}\n\n---\n*Auto-generated by n8n workflow 05-tech-scan-every-3-days*\n*Next scan: ${new Date(Date.now() + 72*60*60*1000).toISOString().split('T')[0]}*`;

const filename = `TECH-SCAN-${today}.md`;

return [{ json: { telegramMsg, obsidianNote, filename } }];
